var C_AIR = 343; // 20°C 空气中声速 m/s
var C_LIGHT = 2.99792458e8;
// 声波：声源朝观察者运动 vs>0，观察者朝声源运动 vo>0
function dopplerSound(f, vs, vo, c){ c=(c==null)?C_AIR:c; return f*(c+vo)/(c-vs); }
// 光波（经典近似）：v>0 远离（红移），v<0 接近（蓝移），c 默认光速
function dopplerLight(f, v, c){ c=(c==null)?C_LIGHT:c; return f*(1 - v/c); }
// 波长偏移 Δλ（远离为正）
function wavelengthShift(lambda, v, c){ c=(c==null)?C_LIGHT:c; return lambda*v/c; }
// 红移 z → 退行速度
function redshiftToSpeed(z, c){ c=(c==null)?C_LIGHT:c; return z*c; }
var EXPORTS={ C_AIR:C_AIR, C_LIGHT:C_LIGHT, dopplerSound:dopplerSound, dopplerLight:dopplerLight, wavelengthShift:wavelengthShift, redshiftToSpeed:redshiftToSpeed };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.DopplerForgePure = EXPORTS; }
